                    break;
                case "11":
                    xrTableCell14.Text = rm.GetString("labelRaportiDebia", parametraRaporti.Ci) + " " + "Nentor";
                    break;
                case "12":
                    xrTableCell14.Text = rm.GetString("labelRaportiDebia", parametraRaporti.Ci) + "Dhjetor";
                    break;
                default:
                    break;
            }
}
}

