private void xrTable4_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (monedha == false)
                xrTable4.Visible = false;
            else xrTable4.Visible = true;
}

private void xrTableCell22_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
 if (debiakt != 0)
                e.Result = String.Format("{0:0.000%}", Convert.ToDouble((diferenca / debiakt).ToString()));            
            else e.Result = 0.00;
            e.Handled = true;
}

private void xrTableCell22_SummaryReset(object sender, System.EventArgs e) {
  diferenca = 0.0;
            debiakt = 0.00;
}

private void xrTableCell22_SummaryRowChanged(object sender, System.EventArgs e) {
   debiakt += Convert.ToDouble(GetCurrentColumnValue("DETYRIMIMeparshem").ToString());
           diferenca += Convert.ToDouble(GetCurrentColumnValue("totalikrahasues").ToString());
}

private void Rap_DetyrimetKlienteveSipasAgjenteve_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
      var monedhaKF = parameters.Find(param => param.Emri == "monedhaKF");
monedha = Convert.ToBoolean(monedhaKF.Vlera) ;
}
int row = 0;
private void GroupHeader1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (row % 2 == 0) 
GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportEven"]; 
else GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportOdd"]; 
row++; 
}
